function taskRow(t:R){return <div className="task" key={t.id}><button className={'check '+(t.data.done?'checked':'')} aria-label="Marcar atividade como concluída" onClick={()=>toggleTask(t).catch(e=>notify(e.message))}>{t.data.done&&<Check size={14}/>}</button><div><strong>{t.data.title}</strong><p>{nameSubject(t.data.subject)} · {fmt(t.data.minutes)} {t.data.date<today()&&!t.data.done&&<span className="late"> · Pendente</span>}</p></div><button className="icon" aria-label="Iniciar atividade" onClick={()=>start(t)}><Play size={17}/></button><button className="icon" aria-label="Editar atividade" onClick={()=>setModal({kind:'task',title:'Editar atividade',id:t.id,data:t.data})}><MoreHorizontal size={18}/></button></div>}
